// SmartHelmet/Software/src/components/LiquidGlassWrapper.jsx
import React from 'react';
import '../styles/LiquidGlassWrapper.css';

export default function LiquidGlassWrapper({ children, className = '', style = {} }) {
  return (
    <div className={`liquid-glass-wrapper ${className}`} style={style}>
      {/* Complex shadow layer */}
      <div className="liquid-glass-overlay" />

      {/* SVG Distortion Filter Layer */}
      <div className="liquid-glass-backdrop" />

      {/* Actual Content */}
      <div className="liquid-glass-content">
        {children}
      </div>

      {/* SVG Definitions for the distortion effect */}
      <svg className="liquid-glass-svg-filter">
        <defs>
          <filter
            id="container-glass"
            x="0%"
            y="0%"
            width="100%"
            height="100%"
            colorInterpolationFilters="sRGB"
          >
            {/* Generate turbulent noise for distortion */}
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.05 0.05"
              numOctaves="1"
              seed="1"
              result="turbulence"
            />
            {/* Blur the turbulence pattern slightly */}
            <feGaussianBlur in="turbulence" stdDeviation="2" result="blurredNoise" />
            {/* Displace the source graphic with the noise */}
            <feDisplacementMap
              in="SourceGraphic"
              in2="blurredNoise"
              scale="20" /* Reduced from 70 to 20 so it looks good on large panels */
              xChannelSelector="R"
              yChannelSelector="B"
              result="displaced"
            />
            {/* Apply overall blur on the final result */}
            <feGaussianBlur in="displaced" stdDeviation="4" result="finalBlur" />
            {/* Output the result */}
            <feComposite in="finalBlur" in2="finalBlur" operator="over" />
          </filter>
        </defs>
      </svg>
    </div>
  );
}
